44	uint16_t lab_fp32_to_fp16(float f) {
45	    const float scale_to_inf  = 0x1.0p+112f;
46	    const float scale_to_zero = 0x1.0p-110f;
47	    float base = (fabsf(f) * scale_to_inf) * scale_to_zero;
48	
49	    const uint32_t w = fp32_to_bits(f);
50	    const uint32_t shl1_w = w + w;
51	    const uint32_t sign = w & UINT32_C(0x80000000);
52	    uint32_t bias = shl1_w & UINT32_C(0xFF000000);
53	    if (bias < UINT32_C(0x71000000)) {
54	        bias = UINT32_C(0x71000000);
55	    }
56	
57	    base = fp32_from_bits((bias >> 1) + UINT32_C(0x07800000)) + base;
58	    const uint32_t bits = fp32_to_bits(base);
59	    const uint32_t exp_bits = (bits >> 13) & UINT32_C(0x00007C00);
60	    const uint32_t mantissa_bits = bits & UINT32_C(0x00000FFF);
61	    const uint32_t nonsign = exp_bits + mantissa_bits;
62	    return (sign >> 16) | (shl1_w > UINT32_C(0xFF000000) ? UINT16_C(0x7E00) : nonsign);
63	}
