99	                           +  ((mask & 0x02) ? qy[1] : -qy[1])
100	                           +  ((mask & 0x04) ? qy[2] : -qy[2])
101	                           +  ((mask & 0x08) ? qy[3] : -qy[3])
102	                           +  ((mask & 0x10) ? qy[4] : -qy[4])
103	                           +  ((mask & 0x20) ? qy[5] : -qy[5])
104	                           +  ((mask & 0x40) ? qy[6] : -qy[6])
105	                           +  ((mask & 0x80) ? qy[7] : -qy[7]);
