123	// fp16 -> fp32 expansion of 4 strided scales without zfh/zvfh (the RTL
124	// target ax45mpv_premium has neither): exact for normals and +-0, subnormal
125	// scales flush to zero (ggml quantizers never produce them). Verified on the
126	// RTL sim by vsim-demo/q1_0/probe.c.
127	static inline vfloat32m2_t lab_expand_fp16_x4(const uint16_t * p, ptrdiff_t stride) {
128	    const vuint16m1_t vh = __riscv_vlse16_v_u16m1(p, stride, 4);
129	    const vuint32m2_t hz = __riscv_vzext_vf2_u32m2(vh, 4);
130	    const vuint32m2_t sign = __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x8000, 4), 16, 4);
131	    vuint32m2_t mag = __riscv_vadd_vx_u32m2(
132	        __riscv_vsll_vx_u32m2(__riscv_vand_vx_u32m2(hz, 0x7FFF, 4), 13, 4),
133	        (uint32_t)112 << 23, 4);
134	    const vbool16_t ez = __riscv_vmseq_vx_u32m2_b16(__riscv_vand_vx_u32m2(hz, 0x7C00, 4), 0, 4);
135	    mag = __riscv_vmerge_vxm_u32m2(mag, 0, ez, 4);
136	    return __riscv_vreinterpret_v_u32m2_f32m2(__riscv_vor_vv_u32m2(sign, mag, 4));
