141	// (vl256 does 4 vmv.x.s + 4 scalar fp16 converts + 4 scalar FMAs per block):
142	// the four group sums are packed into lanes 0..3 of one i16 vector with tiny
143	// slideups, the activation scales are loaded with one strided vlse16 and
144	// applied as a vector, and the float accumulation stays in 4 vector lanes
145	// until one ordered reduction at the end of the row.
146	NOINLINE void ggml_vec_dot_q1_0_q8_0_vl512(const int n, float * GGML_RESTRICT s, const void * GGML_RESTRICT vx, const void * GGML_RESTRICT vy) {
147	    const int qk = QK1_0;
148	    const int nb = n / qk;
149	    assert(n % qk == 0);
150	
151	    const block_q1_0 * GGML_RESTRICT x = vx;
152	    const block_q8_0 * GGML_RESTRICT y = vy;
153	
154	    //LMUL = 1, VLMAX = 32
155	    const size_t vl32 = __riscv_vsetvl_e8m1(32);
156	    assert(vl32 == 32);
157	    UNUSED(vl32);
158	
159	    const vint16m1_t zero = __riscv_vmv_v_x_i16m1(0, 1);
160	    vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, 4);
161	
162	    for (int ib = 0; ib < nb; ++ib) {
163	        const float d0 = GGML_CPU_FP16_TO_FP32(x[ib].d);
164	        const block_q8_0 * GGML_RESTRICT yb = &y[ib * 4];
165	
166	        const vbool8_t m0 = __riscv_vlm_v_b8(x[ib].qs,      32);
167	        const vbool8_t m1 = __riscv_vlm_v_b8(x[ib].qs +  4, 32);
168	        const vbool8_t m2 = __riscv_vlm_v_b8(x[ib].qs +  8, 32);
169	        const vbool8_t m3 = __riscv_vlm_v_b8(x[ib].qs + 12, 32);
170	        const vint8m1_t q0 = __riscv_vle8_v_i8m1(yb[0].qs, 32);
171	        const vint8m1_t q1 = __riscv_vle8_v_i8m1(yb[1].qs, 32);
172	        const vint8m1_t q2 = __riscv_vle8_v_i8m1(yb[2].qs, 32);
173	        const vint8m1_t q3 = __riscv_vle8_v_i8m1(yb[3].qs, 32);
174	        const vint8m1_t s0 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q0, 32), q0, m0, 32);
175	        const vint8m1_t s1 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q1, 32), q1, m1, 32);
176	        const vint8m1_t s2 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q2, 32), q2, m2, 32);
177	        const vint8m1_t s3 = __riscv_vmerge_vvm_i8m1(__riscv_vneg_v_i8m1(q3, 32), q3, m3, 32);
178	
179	        vint16m1_t gs       = __riscv_vwredsum_vs_i8m1_i16m1(s0, zero, 32);
180	        const vint16m1_t r1 = __riscv_vwredsum_vs_i8m1_i16m1(s1, zero, 32);
181	        const vint16m1_t r2 = __riscv_vwredsum_vs_i8m1_i16m1(s2, zero, 32);
182	        const vint16m1_t r3 = __riscv_vwredsum_vs_i8m1_i16m1(s3, zero, 32);
183	
184	        // pack the four group sums into lanes 0..3 (no vector->scalar moves);
185	        // all slideups run at vl=4: lanes above each offset are overwritten by
186	        // the later slideups, so only lane `offset` of each survives
187	        gs = __riscv_vslideup_vx_i16m1(gs, r1, 1, 4);
188	        gs = __riscv_vslideup_vx_i16m1(gs, r2, 2, 4);
189	        gs = __riscv_vslideup_vx_i16m1(gs, r3, 3, 4);
190	        const vint32m2_t gs32 = __riscv_vsext_vf2_i32m2(gs, 4);
191	        const vfloat32m2_t dyf = lab_expand_fp16_x4((const uint16_t *)&yb[0].d, sizeof(block_q8_0));
