193	        // facc += d0 * (dy .* group_sums)
194	        const vfloat32m2_t gsf = __riscv_vfcvt_f_x_v_f32m2(gs32, 4);
195	        facc = __riscv_vfmacc_vf_f32m2(facc, d0, __riscv_vfmul_vv_f32m2(gsf, dyf, 4), 4);
196	    }
