333	            acc += GGML_CPU_FP16_TO_FP32(yb->d) * (float)__riscv_vmv_x_s_i16m1_i16(red);
334	        }
335	
336	        sumf += d0 * acc;
337	    }
338	
339	    *s = sumf;
340	}
341	#endif
342	
343	void ggml_vec_dot_q1_0_q8_0(int n, float * GGML_RESTRICT s, size_t bs, const void * GGML_RESTRICT vx, size_t bx, const void * GGML_RESTRICT vy, size_t by, int nrc) {
344	#if defined(__riscv_v_intrinsic)
345	    assert(nrc == 1);
346	
347	    const size_t vlen_bits = __riscv_vlenb() * 8;
348	
349	    if (vlen_bits >= 512) {
350	        ggml_vec_dot_q1_0_q8_0_vl512(n, s, vx, vy);
351	    } else if (vlen_bits >= 256) {
352	        ggml_vec_dot_q1_0_q8_0_vl256(n, s, vx, vy);
353	    } else if (vlen_bits >= 128) {
354	        ggml_vec_dot_q1_0_q8_0_vl128(n, s, vx, vy);
355	    } else {
356	        ggml_vec_dot_q1_0_q8_0_generic(n, s, bs, vx, bx, vy, by, nrc);
357	    }
358	#else
359	    ggml_vec_dot_q1_0_q8_0_generic(n, s, bs, vx, bx, vy, by, nrc);
360	#endif
361	}
