1	// Correctness harness for the Q1_0 x Q8_0 vec_dot kernels.
2	//
3	// Two gates per case:
4	// - bit-exact vs the scalar reference, for kernels that do the same float ops
5	//   in the same order (generic, vl256, vl128). Build uses -ffp-contract=off
6	//   so neither side gets FMA-fused.
7	// - normalized error vs a double-precision reference < NORM_ERR_MAX, for
8	//   kernels that reorder the float accumulation (vl512: per-group sums packed
9	//   into vector lanes, FMA, one ordered reduction per row).
10	//
11	// Data domain matches ggml: q8 quants are in [-127,127] (ggml Q8_0 never
12	// emits -128; vneg on int8 -128 wraps and would falsely diverge from the
13	// scalar reference, which negates in 32-bit).
14	//
15	// --inject: flips one weight bit after taking a baseline and requires the
16	// dispatcher result to change. Proves the harness can detect a broken kernel.
17	// --bench:  ns/call per kernel on one large row. Under QEMU this tracks
18	// instruction count, not real latency; use vsim/FPGA for cycles.
19	
20	#include "q1_0.h"
21	
22	#include <math.h>
23	#include <stdio.h>
24	#include <stdlib.h>
25	#include <string.h>
26	#include <time.h>
27	
28	#if defined(__riscv_v_intrinsic)
29	#include <riscv_vector.h>
30	#endif
31	
32	#define NORM_ERR_MAX 1e-4
33	
34	static uint64_t rng_state = 0x243F6A8885A308D3ull;
35	
36	static uint64_t rng_next(void) {
37	    rng_state ^= rng_state << 13;
38	    rng_state ^= rng_state >> 7;
39	    rng_state ^= rng_state << 17;
40	    return rng_state;
41	}
42	
43	static uint16_t rand_fp16(float lo, float hi) {
44	    const float v = lo + (hi - lo) * ((rng_next() >> 11) * 0x1.0p-53f);
45	    return lab_fp32_to_fp16(v);
46	}
47	
48	static void fill_random(block_q1_0 * x, int nbx, block_q8_0 * y, int nby) {
49	    for (int i = 0; i < nbx; ++i) {
50	        x[i].d = rand_fp16(-2.0f, 2.0f);
51	        for (int j = 0; j < QK1_0 / 8; ++j) {
52	            x[i].qs[j] = (uint8_t)rng_next();
53	        }
54	    }
55	    for (int i = 0; i < nby; ++i) {
56	        y[i].d = rand_fp16(0.001f, 1.0f);
57	        for (int j = 0; j < QK8_0; ++j) {
58	            y[i].qs[j] = (int8_t)((int)(rng_next() % 255) - 127); // [-127,127]
59	        }
60	    }
61	}
62	
63	// reference dot in double, plus sum of |terms| for error normalization
64	static double ref_dot_double(const block_q1_0 * x, const block_q8_0 * y, int n, double * sum_abs) {
65	    double sum = 0.0, sabs = 0.0;
66	    for (int i = 0; i < n / QK1_0; ++i) {
67	        const double d0 = (double)lab_fp16_to_fp32(x[i].d);
68	        for (int k = 0; k < 4; ++k) {
69	            const block_q8_0 * yb = &y[i * 4 + k];
70	            const double d1 = (double)lab_fp16_to_fp32(yb->d);
71	            long sumi = 0;
72	            for (int j = 0; j < QK8_0; ++j) {
73	                const int bit = (x[i].qs[k * 4 + j / 8] >> (j % 8)) & 1;
74	                sumi += bit ? yb->qs[j] : -yb->qs[j];
75	            }
76	            sum  += d0 * d1 * (double)sumi;
77	            sabs += fabs(d0 * d1 * (double)sumi);
78	        }
79	    }
80	    *sum_abs = sabs;
81	    return sum;
82	}
83	
84	static uint32_t f32_bits(float f) {
85	    uint32_t w;
86	    memcpy(&w, &f, sizeof(w));
87	    return w;
88	}
89	
90	// ---- kernels under test ----------------------------------------------------
91	
92	typedef void (*vec_dot8_t)(int, float *, size_t, const void *, size_t, const void *, size_t, int);
93	
94	#if defined(__riscv_v_intrinsic)
95	static void vl512_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
96	    (void)bs; (void)bx; (void)by; (void)nrc;
97	    ggml_vec_dot_q1_0_q8_0_vl512(n, s, vx, vy);
98	}
99	static void vl512w_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
100	    (void)bs; (void)bx; (void)by; (void)nrc;
101	    ggml_vec_dot_q1_0_q8_0_vl512w(n, s, vx, vy);
102	}
103	static void vl256_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
104	    (void)bs; (void)bx; (void)by; (void)nrc;
105	    ggml_vec_dot_q1_0_q8_0_vl256(n, s, vx, vy);
106	}
107	static void vl128_as8(int n, float * s, size_t bs, const void * vx, size_t bx, const void * vy, size_t by, int nrc) {
108	    (void)bs; (void)bx; (void)by; (void)nrc;
109	    ggml_vec_dot_q1_0_q8_0_vl128(n, s, vx, vy);
110	}
111	#endif
112	
113	struct kernel_ent {
114	    const char * name;
115	    vec_dot8_t   fn;
116	    int          bitexact;   // 1: must match scalar reference bit-for-bit
117	    size_t       min_vlen;   // runtime VLEN (bits) required, 0 = always
118	    int          is_dispatcher;
119	};
120	
121	static struct kernel_ent kernels[8];
122	static int n_kernels = 0;
123	
124	static size_t runtime_vlen(void) {
125	#if defined(__riscv_v_intrinsic)
126	    return __riscv_vlenb() * 8;
127	#else
128	    return 0;
129	#endif
130	}
131	
132	static void init_kernels(void) {
133	    const size_t vlen = runtime_vlen();
134	    // dispatcher takes the vl512 path (reordered floats) when VLEN >= 512
135	    kernels[n_kernels++] = (struct kernel_ent){"dispatch", ggml_vec_dot_q1_0_q8_0, vlen < 512, 0, 1};
136	#if defined(__riscv_v_intrinsic)
137	    kernels[n_kernels++] = (struct kernel_ent){"vl512", vl512_as8, 0, 256, 0};   // correct for any VLEN >= 256
138	    kernels[n_kernels++] = (struct kernel_ent){"vl512w", vl512w_as8, 0, 512, 0};
139	    kernels[n_kernels++] = (struct kernel_ent){"vl256", vl256_as8, 1, 256, 0};
140	    kernels[n_kernels++] = (struct kernel_ent){"vl128", vl128_as8, 1, 128, 0};
141	#endif
142	}
143	
144	// ---- correctness -----------------------------------------------------------
145	
146	static int run_case(const block_q1_0 * x, const block_q8_0 * y, int n,
147	                    const char * name, double * max_norm_err, uint32_t * checksum) {
148	    float ref = INFINITY;
149	    ggml_vec_dot_q1_0_q8_0_generic(n, &ref, 0, x, 0, y, 0, 1);
150	
151	    double sum_abs = 0.0;
152	    const double dref = ref_dot_double(x, y, n, &sum_abs);
153	    const double norm = sum_abs > 1e-30 ? sum_abs : 1e-30;
154	
155	    const size_t vlen = runtime_vlen();
156	    int failed = 0;
157	
158	    for (int ki = 0; ki < n_kernels; ++ki) {
159	        const struct kernel_ent * k = &kernels[ki];
160	        if (vlen < k->min_vlen) {
161	            continue;
162	        }
163	        float got = INFINITY;
164	        k->fn(n, &got, 0, x, 0, y, 0, 1);
165	        if (k->is_dispatcher) {
166	            *checksum ^= f32_bits(got);
167	        }
168	
169	        if (k->bitexact && f32_bits(ref) != f32_bits(got)) {
170	            printf("FAIL %-8s %-12s n=%5d bit-exact: ref=%.9g (0x%08x) got=%.9g (0x%08x)\n",
171	                   k->name, name, n, (double)ref, f32_bits(ref), (double)got, f32_bits(got));
172	            failed = 1;
173	        }
174	        const double norm_err = fabs((double)got - dref) / norm;
175	        if (norm_err > *max_norm_err) {
176	            *max_norm_err = norm_err;
177	        }
178	        if (norm_err > NORM_ERR_MAX) {
179	            printf("FAIL %-8s %-12s n=%5d norm_err=%.3g vs double ref %.9g (got %.9g)\n",
180	                   k->name, name, n, norm_err, dref, (double)got);
181	            failed = 1;
182	        }
183	    }
184	    return failed;
185	}
186	
187	static int test_size(int n, int trials, uint32_t * checksum) {
188	    const int nbx = n / QK1_0;
189	    const int nby = n / QK8_0;
190	    block_q1_0 * x = malloc((size_t)nbx * sizeof(block_q1_0));
191	    block_q8_0 * y = malloc((size_t)nby * sizeof(block_q8_0));
192	
193	    int failed = 0;
194	    double max_norm_err = 0.0;
195	
196	    for (int t = 0; t < trials; ++t) {
197	        fill_random(x, nbx, y, nby);
198	        failed += run_case(x, y, n, "random", &max_norm_err, checksum);
199	    }
200	
201	    // edge cases
202	    fill_random(x, nbx, y, nby);
203	    for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0x00, QK1_0 / 8);
204	    failed += run_case(x, y, n, "bits=0x00", &max_norm_err, checksum);
205	
206	    for (int i = 0; i < nbx; ++i) memset(x[i].qs, 0xFF, QK1_0 / 8);
207	    failed += run_case(x, y, n, "bits=0xFF", &max_norm_err, checksum);
208	
209	    fill_random(x, nbx, y, nby);
210	    for (int i = 0; i < nby; ++i) memset(y[i].qs, 127, QK8_0);
211	    failed += run_case(x, y, n, "q8=+127", &max_norm_err, checksum);
212	
213	    for (int i = 0; i < nby; ++i) memset(y[i].qs, -127, QK8_0);
214	    failed += run_case(x, y, n, "q8=-127", &max_norm_err, checksum);
215	
216	    fill_random(x, nbx, y, nby);
217	    for (int i = 0; i < nbx; ++i) x[i].d = 0;
218	    failed += run_case(x, y, n, "d0=0", &max_norm_err, checksum);
219	
220	    printf("n=%5d: %3d cases x %d kernels, %s, max_norm_err=%.3g\n",
221	           n, trials + 5, n_kernels, failed ? "FAIL" : "ok", max_norm_err);
222	    free(x);
223	    free(y);
224	    return failed;
225	}
226	
227	// prove the harness detects a wrong kernel: flip one weight bit, result must change
228	static int test_inject(void) {
229	    const int n = 512;
230	    block_q1_0 x[512 / QK1_0];
231	    block_q8_0 y[512 / QK8_0];
232	    fill_random(x, 512 / QK1_0, y, 512 / QK8_0);
233	
234	    // make the target element's contribution unmissable
235	    x[1].d = lab_fp32_to_fp16(1.0f);
236	    y[1 * 4 + 2].d = lab_fp32_to_fp16(1.0f);
237	    y[1 * 4 + 2].qs[13] = 100;
238	
239	    float base = 0, after = 0;
240	    ggml_vec_dot_q1_0_q8_0(n, &base, 0, x, 0, y, 0, 1);
241	
242	    x[1].qs[2 * 4 + 13 / 8] ^= (uint8_t)(1u << (13 % 8)); // flip sign bit of element 13, group 2, block 1
243	    ggml_vec_dot_q1_0_q8_0(n, &after, 0, x, 0, y, 0, 1);
244	
245	    if (f32_bits(base) == f32_bits(after)) {
246	        printf("INJECT FAIL: flipped weight bit not detected (result unchanged: %.9g)\n", (double)base);
247	        return 1;
248	    }
249	    printf("INJECT ok: flipped weight bit changed result %.9g -> %.9g (delta ~ %g, expect ~200)\n",
250	           (double)base, (double)after, (double)after - (double)base);
251	    return 0;
252	}
253	
254	// ---- benchmark (instruction-count proxy under QEMU) ------------------------
255	
256	static int test_bench(void) {
257	    const int n = 8192;
258	    const int reps = 2000;
259	    const int nbx = n / QK1_0;
260	    const int nby = n / QK8_0;
261	    block_q1_0 * x = malloc((size_t)nbx * sizeof(block_q1_0));
262	    block_q8_0 * y = malloc((size_t)nby * sizeof(block_q8_0));
263	    fill_random(x, nbx, y, nby);
264	
265	    const size_t vlen = runtime_vlen();
266	    double base_ns = 0.0;
267	
268	    printf("bench: n=%d, reps=%d (QEMU: proxy for instruction count only)\n", n, reps);
269	    for (int ki = 0; ki < n_kernels; ++ki) {
270	        const struct kernel_ent * k = &kernels[ki];
271	        if (k->is_dispatcher || vlen < k->min_vlen) {
272	            continue;
273	        }
274	        float s = 0;
275	        k->fn(n, &s, 0, x, 0, y, 0, 1); // warm up
276	
277	        struct timespec t0, t1;
278	        clock_gettime(CLOCK_MONOTONIC, &t0);
279	        for (int r = 0; r < reps; ++r) {
280	            k->fn(n, &s, 0, x, 0, y, 0, 1);
281	        }
282	        clock_gettime(CLOCK_MONOTONIC, &t1);
283	        const double ns = (double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec);
284	        const double per_call = ns / reps;
285	        if (base_ns == 0.0) {
286	            base_ns = per_call;
287	        }
288	        printf("  %-8s %10.0f ns/row  speedup vs %s: %.2fx  (result %.6g)\n",
289	               k->name, per_call, kernels[1].name, base_ns / per_call, (double)s);
290	    }
291	
292	    // scalar reference for context
293	    {
294	        float s = 0;
295	        struct timespec t0, t1;
296	        clock_gettime(CLOCK_MONOTONIC, &t0);
297	        for (int r = 0; r < reps / 10; ++r) {
298	            ggml_vec_dot_q1_0_q8_0_generic(n, &s, 0, x, 0, y, 0, 1);
299	        }
300	        clock_gettime(CLOCK_MONOTONIC, &t1);
301	        const double ns = (double)(t1.tv_sec - t0.tv_sec) * 1e9 + (double)(t1.tv_nsec - t0.tv_nsec);
302	        printf("  %-8s %10.0f ns/row\n", "generic", ns / (reps / 10));
303	    }
304	
305	    free(x);
306	    free(y);
307	    return 0;
308	}
309	
310	int main(int argc, char ** argv) {
311	    // canary values for the fp16 conversion this harness depends on
312	    if (lab_fp16_to_fp32(0x3C00) != 1.0f || lab_fp16_to_fp32(0xC000) != -2.0f ||
313	        lab_fp16_to_fp32(0x7BFF) != 65504.0f || lab_fp32_to_fp16(1.0f) != 0x3C00 ||
314	        lab_fp32_to_fp16(-2.0f) != 0xC000) {
315	        printf("FAIL: fp16 conversion self-test\n");
316	        return 1;
317	    }
318	
319	    init_kernels();
320	
321	#if defined(__riscv_v_intrinsic)
322	    const size_t vlen_bits = runtime_vlen();
323	    const char * path = vlen_bits >= 512 ? "vl512" : vlen_bits >= 256 ? "vl256" : vlen_bits >= 128 ? "vl128" : "generic";
324	    printf("build: RVV, VLEN=%zu bits -> dispatcher path: %s\n", vlen_bits, path);
325	#else
326	    printf("build: scalar (dispatcher == generic reference)\n");
327	#endif
328	
329	    if (argc > 1 && strcmp(argv[1], "--inject") == 0) {
330	        return test_inject();
331	    }
332	    if (argc > 1 && strcmp(argv[1], "--bench") == 0) {
333	        return test_bench();
334	    }
335	
336	    const int sizes[] = {128, 256, 512, 1024, 4096, 5120, 8192};
337	    int failed = 0;
338	    uint32_t checksum = 0;
339	    for (size_t i = 0; i < sizeof(sizes) / sizeof(sizes[0]); ++i) {
340	        failed += test_size(sizes[i], 50, &checksum);
341	    }
342	    printf("%s (dispatcher checksum 0x%08x - comparable between runs taking the same dispatcher path)\n",
343	           failed ? "FAILED" : "ALL PASS", checksum);
344	    return failed ? 1 : 0;
345	}
